package com.telecom.support.payment;

import java.math.BigDecimal;
import java.time.Instant;
import org.springframework.http.HttpHeaders;

/**
 * Port to the hosted payment gateway (design 02-customer backend §8, §3.1; CUS-08.2–08.4, NFR-AVAIL). Slice 02 ships only
 * {@link MockPaymentGateway}; the real adapter comes in slice 06.
 *
 * <p>The payment {@code reference} ({@code PAY-…}) is generated by this application and sent as the merchant reference
 * <b>before</b> the gateway answers, so a payment whose {@link #createCheckout} timed out can still be reconciled with
 * {@link #getStatus}. No card data passes through this port (NFR-PRIV, §12): the customer enters it on the gateway's own
 * page, and only the method, transaction id and amounts come back.
 */
public interface PaymentGateway {

    /** Payment method reported by the gateway; the values are the {@code payments.method} values. */
    enum Method { UPI, CARD, NETBANKING, WALLET }

    /** What the gateway knows about a merchant reference. {@link #NOT_FOUND}: no session was ever created for it. */
    enum GatewayStatus { PENDING, SUCCEEDED, FAILED, EXPIRED, NOT_FOUND }

    /** Webhook event types ({@code GatewayWebhookEvent.type}). */
    enum EventType {
        SUCCEEDED("payment.succeeded"), FAILED("payment.failed"), EXPIRED("payment.expired");

        private final String wireName;

        EventType(String wireName) {
            this.wireName = wireName;
        }

        /** The value on the wire, e.g. {@code payment.succeeded}. */
        public String wireName() {
            return wireName;
        }

        /** The type for a wire value, or null when unknown. */
        public static EventType fromWireName(String value) {
            for (EventType type : values()) {
                if (type.wireName.equals(value)) {
                    return type;
                }
            }
            return null;
        }
    }

    /** A hosted checkout session: the browser is sent to {@code redirectUrl}; the session ends at {@code expiresAt}. */
    record CheckoutSession(String sessionId, String redirectUrl, Instant expiresAt) {}

    /**
     * The gateway's view of a merchant reference. For {@link GatewayStatus#NOT_FOUND} every other field is null;
     * {@code method} and {@code gatewayTxnId} are set once the customer paid (or tried to).
     */
    record GatewayPaymentStatus(GatewayStatus status, String sessionId, Method method, String gatewayTxnId,
                                BigDecimal amount, String currency) {

        static GatewayPaymentStatus notFound() {
            return new GatewayPaymentStatus(GatewayStatus.NOT_FOUND, null, null, null, null, null);
        }
    }

    /**
     * A verified, validated webhook event ({@code GatewayWebhookEvent}). For {@link EventType#SUCCEEDED}
     * {@code gatewayTransactionId} and {@code method} are always set.
     */
    record GatewayEvent(String eventId, EventType type, String paymentReference, String sessionId,
                        String gatewayTransactionId, BigDecimal amount, String currency, Method method,
                        String failureReason, Instant occurredAt) {}

    /**
     * Opens a hosted checkout for {@code paymentRef}. Calling it again for a reference whose session is still open returns
     * that session (the merchant reference is the idempotency key on the gateway side).
     *
     * @throws GatewayUnavailableException the gateway refused the call (connection refused, 5xx): no session exists
     * @throws GatewayTimeoutException     no answer within {@code app.payment.gateway.timeout}: a session may exist, so
     *                                     the payment stays reconcilable by {@code paymentRef}
     */
    CheckoutSession createCheckout(String paymentRef, BigDecimal amount, String currency, String returnUrl);

    /**
     * The gateway's status of {@code paymentRef}; {@link GatewayStatus#NOT_FOUND} when no session was ever created.
     *
     * @throws GatewayUnavailableException or {@link GatewayTimeoutException} when the gateway cannot be reached; the
     *                                     caller leaves the payment unchanged (§3.1: never a transition from unknown)
     */
    GatewayPaymentStatus getStatus(String paymentRef);

    /**
     * Verifies and parses a webhook request: the signature over the <b>raw</b> body bytes and its timestamp tolerance are
     * checked before the body is parsed (§8 order: 401 before 400).
     *
     * @throws WebhookSignatureException missing, malformed or wrong signature, or a timestamp outside the tolerance (401)
     * @throws WebhookPayloadException   the signed body is not a valid {@code GatewayWebhookEvent} (400)
     */
    GatewayEvent verifyWebhook(HttpHeaders headers, byte[] rawBody);

    /** The gateway could not be reached. */
    abstract class GatewayException extends RuntimeException {
        protected GatewayException(String message) {
            super(message);
        }
    }

    /** The gateway refused the call (connection refused or 5xx). */
    class GatewayUnavailableException extends GatewayException {
        public GatewayUnavailableException(String message) {
            super(message);
        }
    }

    /** The gateway did not answer within the client timeout; the outcome is unknown. */
    class GatewayTimeoutException extends GatewayException {
        public GatewayTimeoutException(String message) {
            super(message);
        }
    }

    /** A webhook failed authentication (401). {@link #reason()} is the audit reason. */
    class WebhookSignatureException extends RuntimeException {

        /** Audit reasons of {@code PAYMENT_WEBHOOK_REJECTED} (design §7). */
        public enum Reason {
            BAD_SIGNATURE("bad_signature"), STALE("stale");

            private final String auditValue;

            Reason(String auditValue) {
                this.auditValue = auditValue;
            }

            public String auditValue() {
                return auditValue;
            }
        }

        private final Reason reason;

        public WebhookSignatureException(Reason reason, String message) {
            super(message);
            this.reason = reason;
        }

        public Reason reason() {
            return reason;
        }
    }

    /** A correctly signed webhook body that is not a valid event (400). */
    class WebhookPayloadException extends RuntimeException {
        public WebhookPayloadException(String message) {
            super(message);
        }
    }
}
